<?php
$pageTitle='Laporan';
$pageSubtitle='Rekap aktivitas parkir untuk kebutuhan evaluasi keamanan dan operasional.';
require_once __DIR__ . '/includes/header.php';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$params=[$from,$to];
$summary=$pdo->prepare("SELECT status_akses, jenis_akses, COUNT(*) total FROM access_logs WHERE DATE(waktu_akses) BETWEEN ? AND ? GROUP BY status_akses, jenis_akses");$summary->execute($params);$sumRows=$summary->fetchAll();
$byUser=$pdo->prepare("SELECT COALESCE(u.nama_user,'Tidak Terdaftar') nama, COALESCE(u.jenis_user,'-') jenis, COUNT(*) total FROM access_logs l LEFT JOIN users u ON u.id_user=l.id_user WHERE DATE(l.waktu_akses) BETWEEN ? AND ? GROUP BY nama,jenis ORDER BY total DESC LIMIT 10");$byUser->execute($params);$topUsers=$byUser->fetchAll();
$byDay=$pdo->prepare("SELECT DATE(waktu_akses) tgl, SUM(status_akses='Diterima') diterima, SUM(status_akses='Ditolak') ditolak, COUNT(*) total FROM access_logs WHERE DATE(waktu_akses) BETWEEN ? AND ? GROUP BY DATE(waktu_akses) ORDER BY tgl ASC");$byDay->execute($params);$days=$byDay->fetchAll();
$total=0;$accepted=0;$rejected=0;foreach($sumRows as $s){$total+=(int)$s['total'];if($s['status_akses']=='Diterima')$accepted+=(int)$s['total'];if($s['status_akses']=='Ditolak')$rejected+=(int)$s['total'];}
?>
<div class="card"><form class="search-form"><input class="input" type="date" name="from" value="<?= e($from) ?>"><input class="input" type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary">Tampilkan</button><button class="btn btn-light" type="button" onclick="window.print()">Cetak Laporan</button><a class="btn btn-success" href="export_logs.php?from=<?= e($from) ?>&to=<?= e($to) ?>">Export CSV</a></form></div>
<div class="grid grid-3" style="margin-top:18px"><div class="card stat"><div class="label">Total Aktivitas</div><div class="number"><?= $total ?></div><div class="note">Periode <?= e($from) ?> s.d <?= e($to) ?></div></div><div class="card stat"><div class="label">Akses Diterima</div><div class="number"><?= $accepted ?></div><div class="note">Kartu valid</div></div><div class="card stat"><div class="label">Akses Ditolak</div><div class="number"><?= $rejected ?></div><div class="note">Kartu bermasalah</div></div></div>
<div class="grid grid-2" style="margin-top:18px"><div class="card"><div class="card-title"><h3>Rekap Harian</h3></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Diterima</th><th>Ditolak</th><th>Total</th></tr></thead><tbody><?php foreach($days as $d): ?><tr><td><?= e(date('d/m/Y',strtotime($d['tgl']))) ?></td><td><span class="badge badge-success"><?= (int)$d['diterima'] ?></span></td><td><span class="badge badge-danger"><?= (int)$d['ditolak'] ?></span></td><td><b><?= (int)$d['total'] ?></b></td></tr><?php endforeach; if(!$days): ?><tr><td colspan="4" class="empty">Tidak ada data pada periode ini.</td></tr><?php endif; ?></tbody></table></div></div><div class="card"><div class="card-title"><h3>Pengguna Paling Aktif</h3></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Jenis</th><th>Total</th></tr></thead><tbody><?php foreach($topUsers as $u): ?><tr><td><?= e($u['nama']) ?></td><td><?= e($u['jenis']) ?></td><td><b><?= (int)$u['total'] ?></b></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once __DIR__ . '/includes/footer.php'; ?>
